import org.junit.Test;
import static org.junit.Assert.*;
import java.util.HashMap;
import java.util.Map;

public class TagTest {

    @Test
    public void getName_DefinedTagReturnsCorrectTagName() {
        Tag tag = new Tag();
        assertEquals("tag", tag.getName());
    }

    @Test
    public void getName_UnknownTagThrowsException() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertNull(emptyTag.getName());
    }

    @Test
    public void normalName_AcceptsNullInputReturnsBlank() {
        assertEquals("", Normalizer.normalName(null));
    }

    @Test
    public void normalName_EmptyStringReturnsBlank() {
        assertEquals("", Normalizer.normalName(""));
    }

    @Test
    public void normalName_SingleCharacterStringReturnSameString() {
        assertEquals("a", Normalizer.normalName("a"));
    }

    @Test
    public void normalName_MultiCharacterStringReturnSameString() {
        assertEquals("hello", Normalizer.normalName("hello"));
    }

    @Test
    public void valueOf_DefinedTagReturnsCorrectTagInstance() {
        Tag tag = new Tag();
        Tag obtainedTag = Tag.valueOf(tag.getName());
        assertSame(tag, obtainedTag);
    }

    @Test
    public void isBlock_ReturnsFalseForInlineTags() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertFalse(emptyTag.isBlock());
        assertFalse(Tag.valueOf("img").isBlock());
    }

    @Test
    public void formatAsBlock_DoesNotChangeBlockTags() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertFalse(emptyTag.formatAsBlock());
        assertFalse(Tag.valueOf("img").formatAsBlock());
    }

    @Test
    public void isInline_ReturnsTrueForInlineTags() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertTrue(emptyTag.isInline());
        assertTrue(Tag.valueOf("span").isInline());
    }

    @Test
    public void isEmpty_ReturnsTrueForEmptyTags() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertTrue(emptyTag.isEmpty());
    }

    @Test
    public void isSelfClosing_ReturnsFalseForNonSelfClosingTags() {
        assertFalse(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertFalse(emptyTag.isSelfClosing());
        assertFalse(Tag.valueOf("img").isSelfClosing());
    }

    @Test
    public void isKnownTag_ReturnsTrueForDefinedTags() {
        assertTrue(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertTrue(emptyTag.isKnownTag());
        assertTrue(Tag.valueOf("div").isKnownTag());
    }

    @Test
    public void isFormListed_ReturnsFalseForNonFormTags() {
        assertFalse(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertFalse(emptyTag.isFormListed());
        assertFalse(Tag.valueOf("img").isFormListed());
    }

    @Test
    public void isFormSubmittable_ReturnsFalseForNonFormTags() {
        assertFalse(Tag.class.isAssignableFrom(EmptyTag.class));
        EmptyTag emptyTag = (EmptyTag) Tag.valueOf("");
        assertFalse(emptyTag.isFormSubmittable());
        assertFalse(Tag.valueOf("img").isFormSubmittable());
    }

    @Test
    public void setSelfClosing_ReturnsSameTagInstance() {
        Tag tag = new Tag();
        Tag obtainedTag = tag.setSelfClosing();
        assertSame(tag, obtainedTag);
    }

    @Test
    public void equals_HandlesNullObjectsCorrectly() {
        Tag tag1 = new Tag();
        Tag tag2 = null;
        assertFalse(tag1.equals(tag2));
        assertTrue(tag2 == null || tag1.equals((Object) tag2));
    }

    @Test
    public void equals_CompareTwoInstancesCorrectly() {
        Tag tag1 = new Tag();
        Tag tag2 = new Tag();
        assertSame(tag1, tag2);
        tag2.setName("test");
        assertNotEquals(tag1, tag2);
